use ark_bls12_381::{Bls12_381, Fr};
use ark_groth16::{checked::{check,check_profiled_with_progress}, prepare_verifying_key, Groth16, ProvingKey, VerifyingKey};
use ark_serialize::{CanonicalDeserialize,CanonicalSerialize};
use ark_std::rand::rngs::OsRng;
use plan_a_joint_circuit::blind_update::{public_inputs, state_leaf, BlindUpdateCircuit, BlindUpdateStatement, StateOpening};
use sha2::{Digest, Sha256};
use serde_json::json;
use std::{env, fs, io::{self,Cursor,Write}, path::{Path, PathBuf}, time::Instant};

fn circuit() -> BlindUpdateCircuit {
    let old=StateOpening{grant_root:Fr::from(11u64),expiry:900,active:true,salt:Fr::from(12u64)};
    let new=StateOpening{grant_root:Fr::from(13u64),expiry:900,active:true,salt:Fr::from(14u64)};
    let mut s=BlindUpdateStatement{config_digest:Fr::from(1u64),deployment:Fr::from(2u64),circuit_id:Fr::from(3u64),owner:Fr::from(4u64),position:5,expiry_cap:1000,admission_version:0,old_leaf:Fr::from(0u64),new_leaf:Fr::from(0u64),old_version:7,new_version:8,old_epoch:9,new_epoch:10};
    s.old_leaf=state_leaf(s.owner,s.old_version,s.old_epoch,s.position,&old);
    s.new_leaf=state_leaf(s.owner,s.new_version,s.new_epoch,s.position,&new);
    BlindUpdateCircuit{statement:s,old,new}
}
fn write<T:CanonicalSerialize>(p:&Path,x:&T){let mut b=Vec::new();x.serialize_compressed(&mut b).unwrap();fs::write(p,b).unwrap();}
fn read(p:&Path)->Vec<u8>{fs::read(p).unwrap()}
fn sha(b:&[u8])->String{hex::encode(Sha256::digest(b))}
fn decode_exact<T:CanonicalDeserialize+CanonicalSerialize>(b:&[u8])->T{let mut c=Cursor::new(b);let x=T::deserialize_compressed(&mut c).unwrap();assert_eq!(c.position() as usize,b.len());let mut out=Vec::new();x.serialize_compressed(&mut out).unwrap();assert_eq!(out,b);x}
fn setup(dir:&Path){assert!(!dir.exists());fs::create_dir_all(dir).unwrap();let t=Instant::now();let(pk,m,sm)=Groth16::<Bls12_381>::generate_random_parameters_with_reduction_and_material_profiled(circuit(),&mut OsRng).unwrap();let setup_ns=t.elapsed().as_nanos();let t=Instant::now();write(&dir.join("pk.bin"),&pk);write(&dir.join("vk.bin"),&pk.vk);write(&dir.join("checking.bin"),&m);let serialization_write_ns=t.elapsed().as_nanos();let(pb,vb,mb)=(read(&dir.join("pk.bin")),read(&dir.join("vk.bin")),read(&dir.join("checking.bin")));println!("{}",json!({"event":"setup","setup_ns":setup_ns,"combined_generator_ns":sm.total_ns,"power_construction_ns":sm.power_construction_ns,"serialization_write_ns":serialization_write_ns,"ordinary_setup_excluding_posthoc_power_loop_ns":sm.total_ns-sm.power_construction_ns,"constraints":m.num_constraints,"instances":m.num_instance_variables,"witnesses":m.num_witness_variables,"domain":m.domain_size,"bytes":{"pk":pb.len(),"vk":vb.len(),"material":mb.len()},"pk_sha256":sha(&pb),"vk_sha256":sha(&vb),"material_sha256":sha(&mb)}));}
fn gate(dir:&Path){let full=Instant::now();let t=Instant::now();let(pb,vb,mb)=(read(&dir.join("pk.bin")),read(&dir.join("vk.bin")),read(&dir.join("checking.bin")));let file_read_ns=t.elapsed().as_nanos();println!("{}",json!({"event":"stage","stage":"file_read","duration_ns":file_read_ns}));io::stdout().flush().unwrap();let t=Instant::now();let(checked,m)=check_profiled_with_progress::<Bls12_381,_>(&pb,&vb,&mb,circuit(),|stage,duration_ns|{println!("{}",json!({"event":"stage","stage":stage,"duration_ns":duration_ns}));io::stdout().flush().unwrap();}).unwrap();let checker_call_ns=t.elapsed().as_nanos();let full_load_ns=full.elapsed().as_nanos();let c=circuit();let inputs=public_inputs(&c.statement);let t=Instant::now();let proof=checked.prove(c,&mut OsRng).unwrap();let prove_ns=t.elapsed().as_nanos();let t=Instant::now();let verified=Groth16::<Bls12_381>::verify_proof(checked.prepared_vk(),&proof,&inputs).unwrap();let verify_ns=t.elapsed().as_nanos();assert!(verified);let mut bad=pb.clone();bad[0]^=0xff;assert!(check::<Bls12_381,_>(&bad,&vb,&mb,circuit()).is_err());println!("{}",json!({"event":"gate","relation":"blind-update","file_read_ns":file_read_ns,"checker_call_ns":checker_call_ns,"full_load_ns":full_load_ns,"shape_template_constructed_inside_checker_call":true,"metrics":{"pk_decode_ns":m.pk_decode_ns,"vk_decode_ns":m.vk_decode_ns,"material_decode_ns":m.material_decode_ns,"relation_ns":m.relation_ns,"powers_ns":m.powers_ns,"reconstruction_ns":m.reconstruction_ns,"direct_query_ns":m.direct_query_ns,"b_cross_ns":m.b_cross_ns,"equation_ns":m.equation_ns,"binding_ns":m.binding_ns,"checker_total_ns":m.total_ns},"bytes":{"pk":pb.len(),"vk":vb.len(),"material":mb.len()},"prove_ns":prove_ns,"verify_ns":verify_ns,"verified":verified,"failed_bundle_rejected":true,"receipt":hex::encode(checked.receipt())}));}
fn ordinary(dir:&Path){let full=Instant::now();let t=Instant::now();let(pb,vb)=(read(&dir.join("pk.bin")),read(&dir.join("vk.bin")));let file_read_ns=t.elapsed().as_nanos();let t=Instant::now();let pk:ProvingKey<Bls12_381>=decode_exact(&pb);let pk_decode_ns=t.elapsed().as_nanos();let t=Instant::now();let vk:VerifyingKey<Bls12_381>=decode_exact(&vb);let vk_decode_ns=t.elapsed().as_nanos();assert_eq!(pk.vk,vk);let t=Instant::now();let _prepared=prepare_verifying_key(&vk);let prepare_vk_ns=t.elapsed().as_nanos();println!("{}",json!({"event":"ordinary_load","relation":"blind-update","file_read_ns":file_read_ns,"pk_decode_ns":pk_decode_ns,"vk_decode_ns":vk_decode_ns,"prepare_vk_ns":prepare_vk_ns,"full_load_ns":full.elapsed().as_nanos(),"canonical_exact":true,"embedded_vk_equal":true,"bytes":{"pk":pb.len(),"vk":vb.len()}}));}
fn main(){let a=env::args().collect::<Vec<_>>();let d=PathBuf::from(&a[2]);match a[1].as_str(){"setup"=>setup(&d),"gate"=>gate(&d),"ordinary"=>ordinary(&d),_=>panic!("setup|gate|ordinary DIR")}}
